  (* [comment removed for export] *)
  Lemma call_body : forall own k RNG st ms {B} (K : Z -> @Monad.M APS B) (Q : B -> APS -> footprint -> machine_state -> Prop),
    1 <= k <= 4 -> match own with None => plen = 0 | Some _ => 0 < plen end -> RUNST own 0x7feb0 k RNG st ms ->
    (forall rc' RNG' st' ms', RUNST own (if k =? 1 then 0x7fee8 else 0x7feb0) (k - 1) RNG' st' ms' -> rc' = 0 -> implMA RNG' (K rc') st' Q ms') ->
    implMA RNG (rc' <- fuzz_oneA AAllocAsan payload ;; io_emit (ioA AAllocAsan) rc' ;;; K rc') st Q ms.
